## 🔧 Suggested Hook Registration Code (Complete)

```c
// my_extension.c
#include "postgres.h"
#include "optimizer/planner.h"

PG_MODULE_MAGIC;

static planner_hook_type prev_planner_hook = NULL;

PlannedStmt*
my_planner_hook(Query* parse, ParamListInfo bound_params)
{
    PlannedStmt* result;

    // Your pre-planning logic here
    my_preprocess_query(parse);

    // Chain to previous hook
    if (prev_planner_hook)
        result = prev_planner_hook(parse, bound_params);
    else
        result = standard_planner(parse, bound_params);

    // Your post-processing logic here
    my_instrument_plan(result);

    return result;
}

void _PG_init(void)
{
    prev_planner_hook = planner_hook;
    planner_hook = my_planner_hook;
}

void _PG_fini(void)
{
    planner_hook = prev_planner_hook;
}
```

